import zipfile
from .exception import InvalidSwSource


class TargetbdValidator(object):

    @staticmethod
    def validate_targetbd(targetbd):
        """validate targetbd file path. Raises exception if file has wrong file extension or has errors.

        :param string targetbd path: Path to targetbd file.

        :return: targetbd path.
        """
        if targetbd.endswith('.zip'):
            TargetbdValidator.test_zipfile(targetbd)
            return targetbd
        else:
            raise InvalidSwSource('Unpacked TargetBD XML files are not supported. Please use a zipped SW package instead.')

    @staticmethod
    def test_zipfile(file_path):
        """test zip file. Raises exception if zip file has errors.

        :param string file_path: Path of zip file.

        """
        try:
            zip_file = zipfile.ZipFile(file_path)
            if zip_file.testzip() is not None:
                raise InvalidSwSource('Targetbd File Error')
        except Exception as e:
            raise e
